using System;
using System.Drawing;
using System.Windows.Forms;
public static class Setup {
 [STAThread] public static void Main(string[] args){UiText.Initialize(args);WindowLayout.InitializeDpi();bool sandbox=Array.IndexOf(args,"--sandbox")>=0,silent=Array.IndexOf(args,"--silent")>=0;Application.EnableVisualStyles();try{if(Array.IndexOf(args,"--install-native")>=0){NativeBackSupport.InstallMachine();return;}if(silent){Installation.Install(sandbox);return;}using(var icon=AppIcon.Create())using(var form=new Form{Icon=icon,Text=UiText.Get("RockTek Remote · Установка"),Size=new Size(580,330),StartPosition=FormStartPosition.CenterScreen,Font=new Font("Segoe UI",11),BackColor=Color.FromArgb(22,28,39),ForeColor=Color.White,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false}){var text=new Label{Location=new Point(28,24),Size=new Size(510,170),Text=UiText.Get("RockTek Remote 2.1.0\n\nОбработчик — для текущего пользователя. Компонент «Назад» требует подтверждения администратора.\n\nПрограмма появится в меню Пуск и списке приложений Windows. Настройки, выбранные приложения и резервные копии OneDrive сохраняются.")};form.Controls.Add(text);var button=new Button{Text=UiText.Get("Установить"),Location=new Point(350,215),Size=new Size(180,44),BackColor=Color.FromArgb(46,79,122),FlatStyle=FlatStyle.Flat};form.Controls.Add(button);button.Click+=(s,e)=>{try{Installation.Install(sandbox);MessageBox.Show(UiText.Get("Установлено. Настройки доступны в меню Пуск. Автозапуск — при следующем входе в Windows."),"RockTek Remote");form.Close();}catch(Exception ex){MessageBox.Show(ex.Message,UiText.Get("Ошибка установки"));}};WindowLayout.ScaleAndFit(form,null);Application.Run(form);}}catch(Exception ex){Environment.ExitCode=1;if(!silent)MessageBox.Show(ex.Message,UiText.Get("Ошибка установки"));else{string path=System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"RockTekRemote","setup-error.txt");System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(path));System.IO.File.WriteAllText(path,ex.ToString());}}}
}
